#!/usr/bin/env node
/**
 * seed-version.mjs — seed a new docs version from the previous one.
 *
 *   node scripts/doc-set/seed-version.mjs --product <id> --to <version> [--from <version>] [--root <checkout>] [--apply]
 *
 * Without --apply it prints the plan and the src/config/products.js change. With --apply it:
 *   - copies docs/<path>/<from>/ to docs/<path>/<to>/ (kb/ folders are skipped; the build copies KB in)
 *     and rewrites /docs/<id>/<from>/ links in the copied pages to /docs/<id>/<to>/
 *   - writes sidebars/<id>/<to>.js in the autogenerated pattern
 *   - prepends the version to the product in src/config/products.js and clears the old isLatest
 * --from defaults to the product's current isLatest version. --root targets another checkout or worktree
 * (default: the repo this script lives in). Refuses to overwrite an existing folder.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const DEFAULT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

/** Locate the product's block in products.js text; returns { start, end, block }. */
const escapeRegExp = v => String(v).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

export function findProductBlock(text, id) {
  const m = text.match(new RegExp(`^  \\{\\n    id: '${escapeRegExp(id)}',`, 'm'));
  if (!m) throw new Error(`Product "${id}" not found in src/config/products.js`);
  const start = m.index;
  const end = text.indexOf('\n  },\n', start);
  if (end === -1) throw new Error(`Could not find the end of the "${id}" block`);
  return { start, end: end + '\n  },\n'.length, block: text.slice(start, end + '\n  },\n'.length) };
}

export function parseVersions(block) {
  const out = [];
  const re = /version: '([^']+)',\n\s+label: '[^']*',\n\s+isLatest: (true|false)/g;
  let m;
  while ((m = re.exec(block))) out.push({ version: m[1], isLatest: m[2] === 'true' });
  return out;
}

export function productPath(block) {
  const m = block.match(/path: '([^']+)'/);
  if (!m) throw new Error('Product has no path');
  return m[1];
}

/** Returns the edited products.js text. */
export function addVersion(text, id, to) {
  const { start, end, block } = findProductBlock(text, id);
  const versions = parseVersions(block);
  if (!versions.length) throw new Error(`"${id}" has no versions`);
  if (versions.some(v => v.version === to)) throw new Error(`"${id}" already has version ${to}`);
  if (versions.length === 1 && versions[0].version === 'current') throw new Error(`"${id}" is a single-version product; update it in place`);
  let next = block.replace(/isLatest: true/g, 'isLatest: false');
  const entry = `      {\n        version: '${to}',\n        label: '${to}',\n        isLatest: true,\n        sidebarFile: './sidebars/${id}/${to}.js',\n      },\n`;
  next = next.replace(/(versions: \[\n)/, `$1${entry}`);
  next = next.replace(/defaultVersion: '[^']*'/, `defaultVersion: '${to}'`);
  return text.slice(0, start) + next + text.slice(end);
}

/** Point doc links at the new version: /docs/<id>/<from>/ becomes /docs/<id>/<to>/ (dotted or underscored). Image paths are shared files and stay. */
/** A sidebar copied from the previous version: point version-specific paths and IDs (<id>/<from>, <id>/<from_underscored>) at the new version. */
export function rewriteSidebar(text, id, from, to) {
  const variants = [[from, to], [from.replace(/\./g, '_'), to.replace(/\./g, '_')]];
  let out = text;
  for (const [f, t] of variants) out = out.replace(new RegExp(`(${escapeRegExp(id)}/)${escapeRegExp(f)}(?![\\w.])`, 'g'), `$1${t}`);
  return out;
}

export function rewriteDocLinks(text, id, from, to) {
  const esc = v => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const variants = [[from, to], [from.replace(/\./g, '_'), to.replace(/\./g, '_')]];
  let out = text;
  for (const [f, t] of variants) out = out.replace(new RegExp(`(/docs/${esc(id)}/)${esc(f)}(?=[/#)"'\\s])`, 'g'), `$1${t}`);
  return out;
}

function copyDir(from, to, rewrite) {
  fs.mkdirSync(to, { recursive: true });
  for (const e of fs.readdirSync(from, { withFileTypes: true })) {
    if (e.name === 'kb' && e.isDirectory()) continue;
    const src = path.join(from, e.name);
    const dst = path.join(to, e.name);
    if (e.isDirectory()) copyDir(src, dst, rewrite);
    else if (rewrite && /\.mdx?$/.test(e.name)) fs.writeFileSync(dst, rewrite(fs.readFileSync(src, 'utf8')));
    else fs.copyFileSync(src, dst);
  }
}

export function run(argv) {
  const arg = n => (argv.includes(n) ? argv[argv.indexOf(n) + 1] : undefined);
  const ROOT = arg('--root') ? path.resolve(arg('--root')) : DEFAULT_ROOT;
  const PRODUCTS = path.join(ROOT, 'src/config/products.js');
  const id = arg('--product');
  const to = arg('--to');
  if (!id || !to) {
    console.error('Usage: node scripts/doc-set/seed-version.mjs --product <id> --to <version> [--from <version>] [--apply]');
    return 2;
  }
  const text = fs.readFileSync(PRODUCTS, 'utf8');
  let edited;
  let from;
  let docsPath;
  try {
    const { block } = findProductBlock(text, id);
    from = arg('--from') || parseVersions(block).find(v => v.isLatest)?.version;
    docsPath = productPath(block);
    edited = addVersion(text, id, to);
  } catch (e) {
    console.error(e.message);
    return 1;
  }
  const src = path.join(ROOT, docsPath, from);
  const dst = path.join(ROOT, docsPath, to);
  const sidebar = path.join(ROOT, 'sidebars', id, `${to}.js`);
  if (!fs.existsSync(src)) { console.error(`Source folder ${src} does not exist`); return 1; }
  if (fs.existsSync(dst)) { console.error(`Target folder ${dst} already exists; refusing to overwrite`); return 1; }
  console.log(`Seed ${id} ${to} from ${from}`);
  console.log(`  copy    ${path.relative(ROOT, src)} -> ${path.relative(ROOT, dst)} (kb/ skipped; /docs/${id}/${from}/ links rewritten to ${to})`);
  console.log(`  create  ${path.relative(ROOT, sidebar)}`);
  console.log(`  edit    src/config/products.js: add ${to} as latest, set ${from} isLatest: false`);
  if (!argv.includes('--apply')) { console.log('Dry run. Pass --apply to make the changes.'); return 0; }
  copyDir(src, dst, t => rewriteDocLinks(t, id, from, to));
  fs.mkdirSync(path.dirname(sidebar), { recursive: true });
  const prev = path.join(ROOT, 'sidebars', id, `${from}.js`);
  const prevText = fs.existsSync(prev) ? fs.readFileSync(prev, 'utf8') : null;
  const sidebarText = prevText === null ? "module.exports = {\n  sidebar: [{ type: 'autogenerated', dirName: '.' }],\n};\n" : rewriteSidebar(prevText, id, from, to);
  fs.writeFileSync(sidebar, sidebarText);
  if (prevText !== null && sidebarText !== prevText) console.log(`  rewrote version-specific paths in ${path.relative(ROOT, sidebar)} from ${from} to ${to}`);
  if (prevText !== null && sidebarText.includes(from)) console.log(`  check   ${path.relative(ROOT, sidebar)} still mentions ${from}`);
  fs.writeFileSync(PRODUCTS, edited);
  console.log('Done.');
  return 0;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(run(process.argv.slice(2)));
